import sys
import math

res = []

def solve(n, k):
    global res
    if n == 1:
        return
    if k == 1:
        res.append(n)
        return
    for i in range(2, int(math.sqrt(n)) + 2):
        if n % i == 0:
            res.append(i)
            solve(n // i, k - 1)
            return

def main():
    global res
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    solve(n, k)
    if len(res) == 0 or len(res) != k:
        print(-1)
        return
    check = 1
    for el in res:
        check *= el
    if check != n:
        print(-1)
        return
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    main()

